import pytest


def age_at(born: int, now: int) -> int:
    """Return the whole years between birth year and current year.

    Raises ValueError if now < born.
    """
    if now < born:
        raise ValueError(f"Current year ({now}) cannot be earlier than birth year ({born})")
    return now - born


def test_age_at_positive_difference() -> None:
    assert age_at(2000, 2024) == 24
    assert age_at(1990, 2000) == 10


def test_age_at_same_year() -> None:
    assert age_at(2024, 2024) == 0


def test_age_at_negative_years() -> None:
    assert age_at(-50, -20) == 30
    assert age_at(-10, 10) == 20


def test_age_at_invalid_future_birth() -> None:
    with pytest.raises(ValueError):
        age_at(2025, 2024)

